export function findDatasetBenchmarksById(id: string): DatasetBenchmarkRecord | undefined {
  return DATASET_BENCHMARK_DATABASE.find(item => item.id === id);
}

export function getAllDatasetBenchmarksRecords(): DatasetBenchmarkRecord[] {
  return DATASET_BENCHMARK_DATABASE;
}

export function filterDatasetBenchmarksByPredicate(predicate: (item: DatasetBenchmarkRecord) => boolean): DatasetBenchmarkRecord[] {
  return DATASET_BENCHMARK_DATABASE.filter(predicate);
}

export function countDatasetBenchmarksRecords(): number {
  return DATASET_BENCHMARK_DATABASE.length;
}
